pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #16: Harmonic-Residual Balancing
    // We prioritize keeping the post_residual as small as possible (Best Fit),
    // but penalize "near-empty" gaps that are too small to fit future items.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": if the remaining space is small but > 0, 
    // it's often worse than having 0 space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Class logic: Favor bins that leave a residual which is a multiple 
    // of common item sizes or fits the next item perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong preference for leaving space for the next item
            score -= 15.0;
        } else {
            // If the next item won't fit, we want to maximize the current utilization
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. Dynamic Thresholding: As the stream progresses, prioritize closing bins
    // to keep open_bins_count low.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 4. New Bin Logic: Discourage opening a new bin unless the existing fit is 
    // extremely poor (i.e., leaving a large, unusable gap).
    if bin_residual == bin_capacity {
        // This is the cost of starting a new bin. 
        // We only pick this if existing fits are very poor (high score).
        score = 45.0 + (mean_residual * 0.5);
    }

    // 5. Fitting constraints: If this is the last bin that can fit the item, 
    // strongly incentivize using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space (Best Fit principle).
    // Lower residual is better (score decreases).
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill).
    // We penalize residuals in the [1, 9] range as these are often unusable.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / (post + 1.0);
    }

    // Lookahead coupling: If the next item is large, prioritize keeping larger residuals.
    // If the next item is small, favor tight packing now.
    if next_item_size > 0 {
        let diff = (next_item_size as f64 - post) / bin_capacity as f64;
        score += diff * 20.0;
    }

    // Dynamic thresholding based on stream progress.
    // As we approach the end of the stream, prioritize packing density over flexibility.
    let density_weight = 10.0 * (1.0 - progress);
    score += (mean_residual - post) * density_weight;

    // Penalty for opening new bins: Only open if the current fit is extremely poor
    // or if we are forced to.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // We only return a low score if the average packing is already quite poor.
        score = 80.0 + (mean_residual * 0.5);
    } else {
        // If it's an existing bin, favor those that leave room for the next item
        // or fit the current item tightly.
        if fitting_bins_count == 1 {
            score -= 10.0; // Encourage filling the last possible bin.
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Logic: Best Fit (minimize post_residual)
    // 2. Harmonic Penalty: Penalize gaps that cannot fit common item sizes (10-30)
    // If post_residual is small but > 0, it creates "fragmentation".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic Alignment: Penalize residuals that are not multiples of common item sizes
    // This reduces the chance of leaving "dead space" that no future item can occupy.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 5. Fitting Constraint: If this is the only bin that fits the current item, 
    // it is highly valuable (don't force a new bin).
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 6. Global State: If the current bin is empty (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have too many open bins (high fragmentation) 
        // or if the mean residual of existing bins is already very small.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 15.0;
        } else {
            score += 50.0; // Heavily penalize opening new bins unless necessary
        }
    }

    // 7. Progression factor: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (Minimize post_residual)
    // We start with post_residual. Lower is better.

    // 2. Penalty for creating unusable space ("Dead Space")
    // If the remaining space is small but > 0, it's often wasted.
    // If 0 < post_residual < 10, it is likely unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead matching: Reward bins that can fit the next item perfectly
    // If post_residual is exactly the size of the next item, we reward this placement heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // 4. Lookahead matching: Penalize bins that create space that cannot fit the next item
    // If the next item is large, but we leave just enough space that is smaller than it, we penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // 5. Global state management: Avoid proliferation of bins
    // If we have many open bins, prioritize filling the ones that are already emptiest (highest mean_residual).
    // If bin_residual is high (empty-ish bin), we penalize it slightly to force filling fuller bins first.
    if bin_residual > (bin_capacity / 2) {
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Thresholding: New Bin Logic
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have very few fitting options or the current fit is terrible.
        // We set a high base score for new bins to discourage opening them unnecessarily.
        score = 65.0;

        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 7. Last Chance Heuristic
    // If this is the only bin that can fit the item, we lower the score to ensure it is picked.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1..10) that are difficult to fill.
    // We use a sigmoid-like penalty for small post_residuals.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward keeping the mean residual low (Best-Fit principle).
    // As progress increases, become more aggressive about filling bins tightly.
    let tightness_reward = (post / bin_capacity as f64) * (1.0 + progress * 2.0);

    // Lookahead logic: if the next item is large, avoid leaving a small post_residual.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // If this is the only bin that fits, we are forced to take it unless it's terrible.
    // If it's a new bin, penalize based on open_bins_count to encourage reuse.
    let bin_type_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64).powf(1.5) * 5.0
    } else {
        0.0
    };

    // Combine factors:
    // We want a low score, so we add penalties and subtract rewards.
    let mut score = post + dead_space_penalty + lookahead_penalty + bin_type_penalty - (tightness_reward * 10.0);

    // Dynamic constraint: If fitting_bins_count is 1, lower the barrier to accept this bin
    // to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" (small fragments < 10 are rarely useful)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward bins that can accommodate the lookahead item (Best-Fit-Lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic Class approach: Penalize residues that fall into "awkward" fractions of capacity
    // Encouraging tight packing by penalizing mid-range residuals
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += (residual_ratio * 10.0).sin().abs() * 15.0;

    // If this is the only fitting bin, we are forced to take it; 
    // however, we penalize opening a new bin heavily unless the current bins are all poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual is already quite low (bins are full)
        // or if we have very few open bins (avoiding fragmentation early).
        score += 40.0;
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Reward filling bins that are already partially filled (Best Fit principle)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Dynamic scaling based on progression
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
